          "হঠাৎ চিলেকোঠার দিক থেকে একটি মৃদু কিন্তু স্পষ্ট খসখস শব্দ শোনা গেল। আহসান নিঃশব্দে হাত বাড়িয়ে একটি ভারী পিতলের বাতিদান তুলে নিল। সে ইশারায় বাকি দুজনকে পেছনের দিকে সরে যেতে বলল। ধীর পায়ে সে সিঁড়ির দিকে এগোতে লাগল। প্রতিটি কাঠের ধাপ অতিক্রম করার সময় বুকের ভেতরের হৃৎস্পন্দন কানে এসে বাজছিল।",
          "দরজাটি সন্তর্পণে একটু ফাঁক করতেই ঘরের ভেতরে এক অচেনা অবয়ব নজরে এলো। আলো পড়তেই সেই ব্যক্তির মুখ স্পষ্টভাবে উন্মোচিত হলো। আহসান বিস্ময়ে হতবাক হয়ে দু পা পিছিয়ে গেল। \"তুমি? তুমি বেঁচে আছো? কিন্তু কীভাবে সম্ভব?\"",
          "সেই মুখটি এক অদ্ভুত নিষ্ঠুর হাসিতে উদ্ভাসিত হয়ে উঠল। সে ধীরপায়ে এগিয়ে এসে বলল, \"মানুষ যাকে মৃত্যু মনে করে, তা কখনো কখনো কেবল দীর্ঘ এক প্রস্তুতি মাত্র। তোমাদের সুখের প্রাসাদ গুঁড়িয়ে দেওয়ার জন্যই আমি মৃত্যুর ওপার থেকে ফিরে এসেছি।\"",
          "তখনই পেছন থেকে অদ্ভুত এবং শফিক সাহেব ছুটে এলো। এই আকস্মিক মুখোমুখি সাক্ষাতে পুরো অতীত এক নিমেষে তাদের চোখের সামনে ভেসে উঠল। যে মানুষটিকে এতদিন সবাই বন্ধু অথবা শুভাকাঙ্ক্ষী মনে করেছিল, আসলে সেই ছিল সমস্ত চক্রান্ত ও ধ্বংসের মূল পরিকল্পনাকারী!",
